{
  "id": "V058",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "반복되는 휴직 신청 관련 문의를 다루는 목적이 보존되었습니다."
    },
    {
      "field": "action",
      "score": 1,
      "reason": "조건·서류 안내와 답변이 어려운 문의의 인사 담당자 이관이 뷰에 완전히 드러나지 않습니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "휴직 신청의 적용 조건, 제출 서류, 규정으로 답하기 어려운 문의가 모두 언급됩니다."
    },
    {
      "field": "input",
      "score": 1,
      "reason": "게시된 사내 규정이라는 답변 근거는 p3에만 일부 보존되었습니다."
    },
    {
      "field": "output",
      "score": 1,
      "reason": "조건과 서류를 설명하는 답변 및 인사 담당자 이관 결과가 명시되지 않았습니다."
    },
    {
      "field": "constraints",
      "score": 1,
      "reason": "규정으로 답을 확정하기 어려운 문의의 구분은 있으나 승인 및 인사시스템 변경 제외는 언급되지 않습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "뷰에 원문에 없는 기능이 추가되었다고 볼 근거가 없습니다."
    },
    {
      "field": "roles",
      "score": 1,
      "reason": "직원과 인사 담당자의 역할은 원문에 있으나 뷰에는 인사 담당자 이관 역할이 명시되지 않습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "규정으로 답을 확정하기 어려운 문의는 인사 담당자에게 넘기고 싶습니다.",
      "view_quote": "",
      "reason": "세 뷰 모두 해당 문의의 인사 담당자 이관을 언급하지 않습니다."
    },
    {
      "type": "OMISSION",
      "source_quote": "휴직 신청의 승인이나 인사시스템 정보 변경은 포함하지 않습니다.",
      "view_quote": "",
      "reason": "승인 및 인사시스템 정보 변경을 제외한다는 제약이 모든 뷰에서 빠졌습니다."
    }
  ],
  "permission_interpretation": "원문은 휴직 신청 승인과 인사시스템 정보 변경을 포함하지 않으며, 인사 담당자 이관을 원합니다. 뷰는 AI가 승인하거나 정보를 변경한다고 주장하지 않습니다."
}
